/*! Consentio Connected Flow — auto mount + auto-play stepper */
(function(){"use strict";
var BASE="https://cdn.jsdelivr.net/gh/mariegainche-netizen/Webflow@claude/wizardly-cannon-xpo6is/assets/",
FRAG=BASE+"connected-flow.fragment.html",
INT=4500,TH=.35,RT=250,MR=20,
rm=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;

function init(s){
  var st=s.querySelectorAll(".cflow-step"),pa=s.querySelectorAll(".preview-panel"),sw=s.querySelector(".cflow-steps");
  if(!st.length||!pa.length||!sw)return!1;
  var T=st.length,c=0,t=null;
  function sa(i){c=i;for(var k=0;k<st.length;k++){var on=Number(st[k].getAttribute("data-idx"))===i;st[k].classList.toggle("active",on);on?st[k].setAttribute("aria-current","step"):st[k].removeAttribute("aria-current")}for(var j=0;j<pa.length;j++)pa[j].classList.toggle("active",Number(pa[j].getAttribute("data-idx"))===i);sw.style.setProperty("--progress",(i+.5)/T*100+"%")}
  function go(){if(t||rm)return;t=window.setInterval(function(){sa((c+1)%T)},INT)}
  function stop(){t&&(window.clearInterval(t),t=null)}
  function re(){stop();go()}
  for(var k=0;k<st.length;k++)(function(e){e.addEventListener("click",function(){sa(Number(e.getAttribute("data-idx")));re()});e.addEventListener("keydown",function(ev){(ev.key==="Enter"||ev.key===" ")&&(ev.preventDefault(),sa(Number(e.getAttribute("data-idx"))),re())})})(st[k]);
  if("IntersectionObserver"in window){var io=new IntersectionObserver(function(en){en.forEach(function(x){x.isIntersecting?go():stop()})},{threshold:TH});io.observe(s)}else go();
  document.addEventListener("visibilitychange",function(){if(document.hidden)stop();else{var r=s.getBoundingClientRect();r.bottom>0&&r.top<(window.innerHeight||0)&&go()}});
  return!0
}

function boot(r){
  var ss=document.querySelectorAll(".cflow");
  if(!ss.length){if(r>0)return window.setTimeout(function(){boot(r-1)},RT);return}
  var any=!1;
  ss.forEach(function(s){if(s.dataset.cflowReady==="1")return;init(s)&&(s.dataset.cflowReady="1",any=!0)});
  if(!any&&r>0)window.setTimeout(function(){boot(r-1)},RT)
}

function mount(){
  var mounts=document.querySelectorAll("[data-cflow-mount]");
  if(!mounts.length){boot(MR);return}
  var pending=mounts.length;
  mounts.forEach(function(m){
    if(m.dataset.cflowMounted==="1"){if(--pending===0)boot(MR);return}
    m.dataset.cflowMounted="1";
    fetch(FRAG,{cache:"default"}).then(function(r){if(!r.ok)throw new Error("HTTP "+r.status);return r.text()}).then(function(html){
      m.innerHTML=html;
      if(--pending===0)boot(MR)
    }).catch(function(err){
      m.innerHTML='<p style="padding:24px;color:#c00;font-family:sans-serif">Connected Flow : impossible de charger le module ('+err.message+'). Vérifier la connexion et le cache jsDelivr.</p>';
      if(--pending===0)boot(MR)
    })
  })
}

if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",mount);else mount();
})();
